class Entity(ABC):
    """Anything with a stable identity; equality and hashing derive from it."""

    @abstractmethod
    def identity(self) -> str:
        """Return the unique key for this entity."""

    def __eq__(self, other: object) -> bool:
        """Compare identity for entities of the same concrete type."""
        if type(self) is not type(other):
            return NotImplemented
        return self.identity() == other.identity()

    def __hash__(self) -> int:
        """Hash by the concrete type name and identity."""
        return hash((type(self).__name__, self.identity()))

    def __repr__(self) -> str:
        """Return a developer-friendly representation including the identity."""
        return f"{type(self).__name__}({self.identity()!r})"

class PricingStrategy(ABC):
    """Computes an order total from line items."""

    @abstractmethod
    def price(self, items: Sequence["LineItem"]) -> "Money":
        """Return the total for the given items."""

    def __call__(self, items: Sequence["LineItem"]) -> "Money":
        """Convenience alias for :meth:`price`."""
        return self.price(items)

    @staticmethod
    def _sum_subtotals(items: Sequence["LineItem"]) -> "Money":
        """Sum the subtotal of each item, returning a zero Money for empty input."""
        from .models import Money

        if len(items) == 0:
            return Money(0)
        total = Money(0)
        for item in items:
            total = total + item.subtotal
        return total

class Repository(ABC):
    """Keyed storage of entities."""

    @abstractmethod
    def add(self, item: Entity) -> None:
        """Store an entity keyed by its identity."""

    @abstractmethod
    def get(self, key: str) -> Entity:
        """Return the entity for key; raise KeyError if missing."""

    @abstractmethod
    def remove(self, key: str) -> Entity:
        """Remove and return the entity for key; raise KeyError if missing."""

    @abstractmethod
    def __iter__(self) -> Iterator[Entity]:
        """Iterate over stored entities."""

    def __contains__(self, key: object) -> bool:
        """Return whether ``key`` is a string and its entity is present."""
        if not isinstance(key, str):
            return False
        try:
            self.get(key)
        except KeyError:
            return False
        return True

class AuditTrail:
    """Class-based decorator recording call outcomes into an in-memory list.

    When applied it wraps a callable so that, after each invocation, an entry
    such as ``"<label>:<func_name>:ok"`` (or ``:error:<ExcName>`` on failure)
    is appended to an internal list. Entries are retrievable via
    :attr:`entries` and the trail can be reset with :meth:`clear`.
    """

    def __init__(self, label: str = "audit") -> None:
        """Initialise the trail with a non-empty string ``label``."""
        if not isinstance(label, str):
            raise TypeError("label must be str")
        if label.strip() == "":
            raise ValueError("label required")
        self._label = label
        self._entries: List[str] = []

    def __call__(self, func: Callable[..., T]) -> Callable[..., T]:
        """Decorate ``func``; returns a wrapped callable."""
        if not callable(func):
            raise TypeError("func must be callable")
        label = self._label
        entries = self._entries

        @functools.wraps(func)
        def wrapper(*args: object, **kwargs: object) -> T:
            """Invoke the wrapped function and record the outcome."""
            try:
                result = func(*args, **kwargs)
            except Exception as exc:
                entries.append(f"{label}:{func.__name__}:error:{type(exc).__name__}")
                raise
            entries.append(f"{label}:{func.__name__}:ok")
            return result

        return wrapper

    @property
    def entries(self) -> Tuple[str, ...]:
        """Immutable snapshot of recorded entries."""
        return tuple(self._entries)

    def clear(self) -> None:
        """Remove all recorded entries."""
        self._entries.clear()

    def __len__(self) -> int:
        """Return the number of recorded entries."""
        return len(self._entries)

class Category(Enum):
    """Product categories within the warehouse catalogue."""

    ELECTRONICS = "electronics"
    GROCERY = "grocery"
    APPAREL = "apparel"
    HARDWARE = "hardware"

    @classmethod
    def from_label(cls, label: str) -> "Category":
        """Resolve a category from its lowercase label string.

        Raises:
            TypeError: if ``label`` is not a string.
            ValueError: if no member has a matching value.
        """
        if not isinstance(label, str):
            raise TypeError("category label must be str")
        key = label.strip().lower()
        for member in cls:
            if member.value == key:
                return member
        raise ValueError(f"unknown category: {label!r}")

    def __str__(self) -> str:
        """Return the category's value as its string form."""
        return self.value

class OrderStatus(Enum):
    """Lifecycle stages for an order."""

    NEW = "new"
    RESERVED = "reserved"
    SHIPPED = "shipped"
    CANCELLED = "cancelled"

    @property
    def is_terminal(self) -> bool:
        pass

class EventBus:
    """Synchronous publish/subscribe keyed by :class:`EventType`."""

    def __init__(self) -> None:
        """Initialise an empty handler registry."""
        self._handlers: Dict[EventType, List[Callable[..., None]]] = {}

    def subscribe(self, event_type: EventType, handler: Callable[..., None]) -> None:
        """Register ``handler`` to be called when ``event_type`` is published."""
        if not isinstance(event_type, EventType):
            raise TypeError("event_type must be EventType")
        if not callable(handler):
            raise TypeError("handler must be callable")
        self._handlers.setdefault(event_type, []).append(handler)

    def unsubscribe(self, event_type: EventType, handler: Callable[..., None]) -> bool:
        """Remove ``handler`` from ``event_type``; return whether it was present."""
        handlers = self._handlers.get(event_type, [])
        if handler not in handlers:
            return False
        handlers.remove(handler)
        return True

    def publish(self, event_type: EventType, payload: Mapping[str, object]) -> int:
        """Invoke every handler subscribed to ``event_type`` with ``payload``.

        Returns the number of handlers invoked.
        """
        if not isinstance(event_type, EventType):
            raise TypeError("event_type must be EventType")
        if not isinstance(payload, Mapping):
            raise TypeError("payload must be a Mapping")
        count = 0
        for handler in list(self._handlers.get(event_type, [])):
            handler(payload)
            count += 1
        return count

    def __len__(self) -> int:
        """Return the total number of registered handlers across all event types."""
        return sum(len(handlers) for handlers in self._handlers.values())

    def __contains__(self, event_type: object) -> bool:
        pass

class PlaygroundError(Exception):
    """Root of the playground exception hierarchy."""

    pass

class OutOfStockError(InventoryError):
    """Requested quantity exceeds available stock."""

    def __init__(self, sku: str, requested: int, available: int) -> None:
        """Store the SKU, requested amount, and available amount."""
        self.sku = sku
        self.requested = requested
        self.available = available
        super().__init__(
            f"insufficient stock for {sku}: requested {requested}, available {available}"
        )

class UnknownSKUError(InventoryError):
    """SKU is not registered in the product repository."""

    def __init__(self, sku: str) -> None:
        """Store the unknown SKU."""
        self.sku = sku
        super().__init__(f"unknown SKU: {sku}")

class DuplicateEntityError(PlaygroundError):
    """Identity already exists in a repository."""

    def __init__(self, key: str) -> None:
        """Store the duplicate identity key."""
        self.key = key
        super().__init__(f"duplicate entity: {key}")

class InventoryLedger:
    """Tracks on-hand and reserved quantities per SKU."""

    def __init__(self, product_repo: Repository) -> None:
        """Create a ledger backed by ``product_repo`` for SKU validation."""
        if not isinstance(product_repo, Repository):
            raise TypeError("product_repo must be a Repository")
        self._product_repo = product_repo
        self._on_hand: Dict[str, int] = {}
        self._reserved: Dict[str, int] = {}

    def _require_sku(self, sku: str) -> str:
        """Normalise ``sku`` and raise ``UnknownSKUError`` if it is unregistered."""
        sku = normalize_sku(sku)
        if sku not in self._product_repo:
            raise UnknownSKUError(sku)
        return sku

    def add_stock(self, sku: str, quantity: int) -> int:
        """Add ``quantity`` to on-hand stock for ``sku``; return the new total."""
        quantity = ensure_positive_int(quantity, "quantity")
        sku = self._require_sku(sku)
        self._on_hand[sku] = self._on_hand.get(sku, 0) + quantity
        return self._on_hand[sku]

    def available(self, sku: str) -> int:
        """Return on-hand minus reserved for ``sku``."""
        sku = self._require_sku(sku)
        return self._on_hand.get(sku, 0) - self._reserved.get(sku, 0)

    def reserve(self, sku: str, quantity: int) -> ReservationContext:
        """Reserve ``quantity`` of ``sku`` and return a context that can commit or release it."""
        quantity = ensure_positive_int(quantity, "quantity")
        sku = self._require_sku(sku)
        avail = self.available(sku)
        if quantity > avail:
            raise OutOfStockError(sku, quantity, avail)
        self._reserved[sku] = self._reserved.get(sku, 0) + quantity
        return ReservationContext(self, sku, quantity)

    def release(self, sku: str, quantity: int) -> None:
        """Release ``quantity`` previously reserved for ``sku``."""
        quantity = ensure_positive_int(quantity, "quantity")
        sku = self._require_sku(sku)
        reserved = self._reserved.get(sku, 0)
        if quantity > reserved:
            raise InvalidTransitionError(reserved, quantity)
        self._reserved[sku] = reserved - quantity

    def commit(self, sku: str, quantity: int) -> None:
        """Commit ``quantity`` of ``sku``: decrement both reserved and on-hand."""
        quantity = ensure_positive_int(quantity, "quantity")
        sku = self._require_sku(sku)
        reserved = self._reserved.get(sku, 0)
        if quantity > reserved:
            raise InvalidTransitionError(reserved, quantity)
        self._reserved[sku] = reserved - quantity
        self._on_hand[sku] = self._on_hand.get(sku, 0) - quantity

    def __contains__(self, sku: object) -> bool:
        pass

    def __len__(self) -> int:
        """Return the number of SKUs with positive on-hand stock."""
        return sum(1 for qty in self._on_hand.values() if qty > 0)

    def __iter__(self) -> Iterator[str]:
        """Iterate over SKUs with positive on-hand stock, in sorted order."""
        for sku in sorted(k for k, v in self._on_hand.items() if v > 0):
            yield sku

class ReservationContext:
    """Context manager for a reservation; releases on exit unless committed."""

    def __init__(self, ledger: InventoryLedger, sku: str, quantity: int) -> None:
        """Create a held reservation for ``quantity`` of ``sku`` in ``ledger``."""
        self._ledger = ledger
        self._sku = sku
        self._quantity = quantity
        self._state = "held"

    @property
    def state(self) -> str:
        """Return the current reservation state."""
        return self._state

    def __enter__(self) -> ReservationContext:
        """Enter the context; raises if the reservation is not in the held state."""
        if self._state != "held":
            raise InvalidTransitionError(self._state, "held")
        return self

    def __exit__(self, exc_type: object, exc: object, tb: object) -> bool:
        """Release the reservation on exit unless it was committed."""
        if self._state == "held":
            self._ledger.release(self._sku, self._quantity)
            self._state = "released"
        return False

    def commit(self) -> None:
        """Commit the reservation, decrementing stock; raises if not held."""
        if self._state != "held":
            raise InvalidTransitionError(self._state, "committed")
        self._ledger.commit(self._sku, self._quantity)
        self._state = "committed"

    def __repr__(self) -> str:
        """Return a developer-friendly representation."""
        return f"ReservationContext({self._sku!r}, {self._quantity}, {self._state!r})"

class Warehouse(Entity):
    """Named location owning an :class:`InventoryLedger`."""

    def __init__(self, warehouse_id: str, name: str, ledger: InventoryLedger) -> None:
        """Create a warehouse with the given id, name, and ledger."""
        if not isinstance(warehouse_id, str) or warehouse_id.strip() == "":
            raise ValueError("warehouse_id required")
        if not isinstance(ledger, InventoryLedger):
            raise TypeError("ledger must be InventoryLedger")
        self._warehouse_id = warehouse_id
        self._name = name
        self._ledger = ledger

    def identity(self) -> str:
        """Return the warehouse_id as the entity identity."""
        return self._warehouse_id

    @property
    def ledger(self) -> InventoryLedger:
        """Return the warehouse inventory ledger."""
        return self._ledger

    def receive(self, sku: str, quantity: int) -> int:
        """Add stock to the warehouse ledger; return the new on-hand total."""
        return self._ledger.add_stock(sku, quantity)

    def stock_report(self) -> Dict[str, int]:
        pass

    def __repr__(self) -> str:
        """Return a developer-friendly representation."""
        return f"Warehouse({self._warehouse_id!r}, {self._name!r})"

class Money:
    """Immutable integer-cents amount."""

    def __init__(self, cents: int = 0) -> None:
        """Create a monetary amount; cents must be a non-negative ``int``."""
        if isinstance(cents, bool) or not isinstance(cents, int):
            raise TypeError("cents must be int")
        if cents < 0:
            raise ValueError("money cannot be negative")
        self._cents = cents

    @property
    def cents(self) -> int:
        """Return the stored cents value."""
        return self._cents

    def __add__(self, other: Money) -> Money:
        """Return a new Money equal to ``self + other``."""
        if not isinstance(other, Money):
            raise TypeError("can only add Money to Money")
        return Money(self._cents + other._cents)

    def __sub__(self, other: Money) -> Money:
        """Return a new Money equal to ``self - other``.

        Raises:
            TypeError: if ``other`` is not :class:`Money`.
            ValueError: if the result would be negative.
        """
        if not isinstance(other, Money):
            raise TypeError("can only subtract Money from Money")
        difference = self._cents - other._cents
        if difference < 0:
            raise ValueError("subtraction would be negative")
        return Money(difference)

    def __mul__(self, factor: int) -> Money:
        """Return ``self`` multiplied by a non-negative integer."""
        if isinstance(factor, bool) or not isinstance(factor, int):
            raise TypeError("factor must be int")
        if factor < 0:
            raise ValueError("factor cannot be negative")
        return Money(self._cents * factor)

    def __rmul__(self, factor: int) -> Money:
        """Support ``factor * Money`` by delegating to :meth:`__mul__`."""
        return self.__mul__(factor)

    def __eq__(self, other: object) -> bool:
        """Return True if ``other`` is Money with equal cents."""
        if not isinstance(other, Money):
            return NotImplemented
        return self._cents == other._cents

    def __lt__(self, other: Money) -> bool:
        """Return True if ``self`` is strictly less than ``other``."""
        if not isinstance(other, Money):
            return NotImplemented
        return self._cents < other._cents

    def __le__(self, other: Money) -> bool:
        """Return True if ``self`` is less than or equal to ``other``."""
        if not isinstance(other, Money):
            return NotImplemented
        return self._cents <= other._cents

    def __hash__(self) -> int:
        """Hash by the type name and cents value."""
        return hash(("Money", self._cents))

    def __repr__(self) -> str:
        """Return a developer-friendly representation."""
        return f"Money({self._cents})"

    def __str__(self) -> str:
        """Render the amount as a ``$X.YY`` string."""
        return format_cents(self._cents)

    def __bool__(self) -> bool:
        pass

class Product(Entity):
    """Catalog item."""

    def __init__(self, sku: str, name: str, category: Category, unit_price: Money) -> None:
        """Create a product after validating its SKU, name, category, and price."""
        sku = normalize_sku(sku)
        if not isinstance(name, str) or name.strip() == "":
            raise ValueError("name required")
        if not isinstance(category, Category):
            raise TypeError("category must be Category")
        if not isinstance(unit_price, Money):
            raise TypeError("unit_price must be Money")
        self._sku = sku
        self._name = name
        self._category = category
        self._unit_price = unit_price

    @property
    def sku(self) -> str:
        """Return the product SKU."""
        return self._sku

    @property
    def name(self) -> str:
        """Return the product name."""
        return self._name

    @property
    def category(self) -> Category:
        """Return the product category."""
        return self._category

    @property
    def unit_price(self) -> Money:
        """Return the product unit price."""
        return self._unit_price

    def identity(self) -> str:
        """Return the SKU as the entity identity."""
        return self._sku

    def with_price(self, new_price: Money) -> Product:
        """Return a copy of this product with an updated unit price."""
        if not isinstance(new_price, Money):
            raise TypeError("new_price must be Money")
        return Product(self._sku, self._name, self._category, new_price)

    @classmethod
    def from_dict(cls, data: Mapping[str, object]) -> Product:
        """Build a product from a mapping with keys sku, name, category, unit_price_cents."""
        for key in ("sku", "name", "category", "unit_price_cents"):
            if key not in data:
                raise KeyError(key)
        raw_category = data["category"]
        if isinstance(raw_category, str):
            category = Category.from_label(raw_category)
        elif isinstance(raw_category, Category):
            category = raw_category
        else:
            raise TypeError("category must be str or Category")
        unit_price = Money(data["unit_price_cents"])
        return cls(data["sku"], data["name"], category, unit_price)

    @staticmethod
    def is_valid_name(name: str) -> bool:
        """Return True if ``name`` is a string of 1..80 non-blank characters."""
        if not isinstance(name, str):
            return False
        return 1 <= len(name.strip()) <= 80

class LineItem:
    """One SKU with quantity and unit price."""

    def __init__(self, sku: str, quantity: int, unit_price: Money) -> None:
        """Create a line item after validating its SKU, quantity, and price."""
        sku = normalize_sku(sku)
        quantity = ensure_positive_int(quantity, "quantity")
        if not isinstance(unit_price, Money):
            raise TypeError("unit_price must be Money")
        self._sku = sku
        self._quantity = quantity
        self._unit_price = unit_price

    @property
    def sku(self) -> str:
        """Return the line item SKU."""
        return self._sku

    @property
    def quantity(self) -> int:
        """Return the line item quantity."""
        return self._quantity

    @property
    def unit_price(self) -> Money:
        """Return the unit price."""
        return self._unit_price

    @property
    def subtotal(self) -> Money:
        """Return the line item subtotal (unit price times quantity)."""
        return self._unit_price * self._quantity

    def with_quantity(self, quantity: int) -> LineItem:
        """Return a copy of this line item with a new quantity."""
        return LineItem(self._sku, quantity, self._unit_price)

    def __eq__(self, other: object) -> bool:
        """Compare SKU, quantity, and unit price for equality."""
        if not isinstance(other, LineItem):
            return NotImplemented
        return (self._sku, self._quantity, self._unit_price) == (
            other._sku,
            other._quantity,
            other._unit_price,
        )

    def __hash__(self) -> int:
        """Hash by SKU and quantity."""
        return hash((self._sku, self._quantity))

    def __repr__(self) -> str:
        """Return a developer-friendly representation."""
        return f"LineItem({self._sku!r}, {self._quantity}, {self._unit_price!r})"

class Customer(Entity):
    """Buyer with a credit limit. Balance is the amount owed."""

    def __init__(self, customer_id: str, name: str, credit_limit: Money = Money(0)) -> None:
        """Create a customer with the given identity, name, and credit limit."""
        if not isinstance(customer_id, str) or customer_id.strip() == "":
            raise ValueError("customer_id required")
        if not isinstance(name, str) or name.strip() == "":
            raise ValueError("name required")
        if not isinstance(credit_limit, Money):
            raise TypeError("credit_limit must be Money")
        self._customer_id = customer_id
        self._name = name
        self._credit_limit = credit_limit
        self._balance = Money(0)

    @property
    def customer_id(self) -> str:
        """Return the customer identity."""
        return self._customer_id

    @property
    def name(self) -> str:
        """Return the customer name."""
        return self._name

    @property
    def credit_limit(self) -> Money:
        """Return the credit limit."""
        return self._credit_limit

    @property
    def balance(self) -> Money:
        """Return the current outstanding balance."""
        return self._balance

    def identity(self) -> str:
        """Return the customer_id as the entity identity."""
        return self._customer_id

    def can_afford(self, total: Money) -> bool:
        pass

    def charge(self, total: Money) -> None:
        """Increase the balance by ``total``, raising if the limit would be exceeded."""
        if not self.can_afford(total):
            raise ValueError("credit limit exceeded")
        self._balance = self._balance + total

class OrderStateMachine:
    """Legal OrderStatus transitions, data-driven via TRANSITIONS."""

    TRANSITIONS: Dict[OrderStatus, FrozenSet[OrderStatus]] = {
        OrderStatus.NEW: frozenset({OrderStatus.RESERVED, OrderStatus.CANCELLED}),
        OrderStatus.RESERVED: frozenset({OrderStatus.SHIPPED, OrderStatus.CANCELLED}),
        OrderStatus.SHIPPED: frozenset(),
        OrderStatus.CANCELLED: frozenset(),
    }

    @staticmethod
    def allowed_from(status: OrderStatus) -> FrozenSet[OrderStatus]:
        """Return the set of statuses reachable from ``status``."""
        if not isinstance(status, OrderStatus):
            raise TypeError("status must be OrderStatus")
        return OrderStateMachine.TRANSITIONS[status]

    def can_transition(self, source: OrderStatus, target: OrderStatus) -> bool:
        """Return whether ``target`` is reachable from ``source``."""
        return target in OrderStateMachine.allowed_from(source)

    def transition(self, source: OrderStatus, target: OrderStatus) -> OrderStatus:
        pass

    def __call__(self, source: OrderStatus, target: OrderStatus) -> OrderStatus:
        """Convenience alias for :meth:`transition`."""
        return self.transition(source, target)

class Order:
    """Customer order with items, status, and pricing."""

    def __init__(self, order_id: str, customer: Customer, pricing: PricingStrategy) -> None:
        """Create a new order in the NEW status for ``customer``."""
        if not isinstance(order_id, str) or order_id.strip() == "":
            raise ValueError("order_id required")
        if not isinstance(customer, Customer):
            raise TypeError("customer must be Customer")
        if not isinstance(pricing, PricingStrategy):
            raise TypeError("pricing must be PricingStrategy")
        self._order_id = order_id
        self._customer = customer
        self._pricing = pricing
        self._items: List[LineItem] = []
        self._status: OrderStatus = OrderStatus.NEW
        self._machine = OrderStateMachine()

    @property
    def order_id(self) -> str:
        """Return the order identity."""
        return self._order_id

    @property
    def customer(self) -> Customer:
        """Return the owning customer."""
        return self._customer

    @property
    def status(self) -> OrderStatus:
        """Return the current order status."""
        return self._status

    @property
    def items(self) -> Tuple[LineItem, ...]:
        """Return a tuple copy of the order's line items."""
        return tuple(self._items)

    @property
    def total(self) -> Money:
        """Return the total price of all line items under this order's pricing."""
        return self._pricing.price(self._items)

    def add_item(self, item: LineItem) -> None:
        """Append ``item``, merging with an existing line for the same SKU."""
        if not isinstance(item, LineItem):
            raise TypeError("item must be LineItem")
        if self._status is not OrderStatus.NEW:
            raise InvalidTransitionError(self._status, OrderStatus.NEW)
        for index, existing in enumerate(self._items):
            if existing.sku == item.sku:
                self._items[index] = existing.with_quantity(existing.quantity + item.quantity)
                return
        self._items.append(item)

    def advance(self, target: OrderStatus) -> None:
        """Transition the order to ``target`` status, raising if not allowed."""
        new_status = self._machine.transition(self._status, target)
        self._status = new_status

    def __len__(self) -> int:
        pass

    def __iter__(self) -> Iterator[LineItem]:
        """Iterate over a tuple snapshot of the order's line items."""
        return iter(tuple(self._items))

    def __eq__(self, other: object) -> bool:
        """Compare orders by identity."""
        if not isinstance(other, Order):
            return NotImplemented
        return self._order_id == other._order_id

    def __hash__(self) -> int:
        """Hash by type name and order id."""
        return hash(("Order", self._order_id))

    def __repr__(self) -> str:
        """Return a developer-friendly representation."""
        return f"Order({self._order_id!r}, {self._status.value})"

class OrderBuilder:
    """Fluent construction of an :class:`Order`."""

    def __init__(self, customer: Customer, pricing: PricingStrategy) -> None:
        """Create a builder for ``customer`` and ``pricing``."""
        if not isinstance(customer, Customer):
            raise TypeError("customer must be Customer")
        if not isinstance(pricing, PricingStrategy):
            raise TypeError("pricing must be PricingStrategy")
        self._customer = customer
        self._pricing = pricing
        self._lines: List[Tuple[str, int, Money]] = []

    @classmethod
    def for_customer(cls, customer: Customer) -> OrderBuilder:
        """Create a builder with default :class:`FlatPricing` for ``customer``."""
        return cls(customer, FlatPricing())

    def add(self, sku: str, quantity: int, unit_price: Money) -> OrderBuilder:
        """Record a line item and return self for chaining."""
        item = LineItem(sku, quantity, unit_price)
        self._lines.append((item.sku, item.quantity, item.unit_price))
        return self

    def build(self, order_id: str) -> Order:
        """Construct and return the order; raises if no lines were recorded."""
        if len(self._lines) == 0:
            raise ValueError("no items")
        order = Order(order_id, self._customer, self._pricing)
        for sku, quantity, unit_price in self._lines:
            order.add_item(LineItem(sku, quantity, unit_price))
        return order

    def __len__(self) -> int:
        """Return the number of recorded lines."""
        return len(self._lines)

    def __bool__(self) -> bool:
        """Return True when at least one line has been recorded."""
        return len(self) > 0

class OrderLog:
    """Ordered, deduplicated record of orders; iterable."""

    def __init__(self) -> None:
        """Create an empty order log."""
        self._orders: List[Order] = []

    def record(self, order: Order) -> None:
        """Append ``order``; raises if an order with the same id is already logged."""
        if not isinstance(order, Order):
            raise TypeError("order must be Order")
        for existing in self._orders:
            if existing.order_id == order.order_id:
                raise DuplicateEntityError(order.order_id)
        self._orders.append(order)

    def by_status(self, status: OrderStatus) -> Iterator[Order]:
        pass

    def __getitem__(self, index: int) -> Order:
        """Return the order at ``index``."""
        return self._orders[index]

    def __len__(self) -> int:
        """Return the number of logged orders."""
        return len(self._orders)

    def __iter__(self) -> Iterator[Order]:
        """Iterate over the logged orders."""
        yield from list(self._orders)

class FlatPricing(PricingStrategy):
    """Sum of subtotals plus flat tax in basis points."""

    def __init__(self, tax_bps: int = 0) -> None:
        """Create a pricing strategy with a tax rate in ``tax_bps`` basis points."""
        if isinstance(tax_bps, bool) or not isinstance(tax_bps, int):
            raise TypeError("tax_bps must be int")
        if tax_bps < 0 or tax_bps > 10000:
            raise ValueError("tax_bps must be 0..10000")
        self._tax_bps = tax_bps

    @property
    def tax_bps(self) -> int:
        """Return the tax rate in basis points."""
        return self._tax_bps

    def price(self, items: Sequence[LineItem]) -> Money:
        """Return the subtotal plus the configured flat tax."""
        subtotal = self._sum_subtotals(items)
        if self._tax_bps == 0:
            return subtotal
        tax = Money(subtotal.cents * self._tax_bps // 10000)
        return subtotal + tax

class BulkDiscountPricing(PricingStrategy):
    """Wraps another strategy; applies a percent discount when total quantity meets a threshold."""

    def __init__(self, base: PricingStrategy, threshold: int, percent_off: int) -> None:
        """Create a strategy that discounts ``base`` totals above ``threshold`` quantity."""
        if not isinstance(base, PricingStrategy):
            raise TypeError("base must be PricingStrategy")
        threshold = ensure_positive_int(threshold, "threshold")
        if isinstance(percent_off, bool) or not isinstance(percent_off, int):
            raise TypeError("percent_off must be int")
        if percent_off < 0 or percent_off > 100:
            raise ValueError("percent_off must be 0..100")
        self._base = base
        self._threshold = threshold
        self._percent_off = percent_off

    @property
    def threshold(self) -> int:
        """Return the qualifying total quantity."""
        return self._threshold

    @property
    def percent_off(self) -> int:
        """Return the discount percentage."""
        return self._percent_off

    def price(self, items: Sequence[LineItem]) -> Money:
        pass

    def __repr__(self) -> str:
        """Return a developer-friendly representation."""
        return f"BulkDiscountPricing(threshold={self._threshold}, percent_off={self._percent_off})"

class InMemoryRepository(Repository):
    """Dict-backed repository keyed by ``item.identity()``."""

    def __init__(self, entity_type: type) -> None:
        """Create a repository restricted to instances of ``entity_type``."""
        if not isinstance(entity_type, type):
            raise TypeError("entity_type must be a type")
        self._entity_type = entity_type
        self._store: Dict[str, Entity] = {}

    def add(self, item: Entity) -> None:
        """Store ``item`` keyed by its identity; raises on duplicate or wrong type."""
        if not isinstance(item, self._entity_type):
            raise TypeError(f"item must be {self._entity_type.__name__}")
        key = item.identity()
        if key in self._store:
            raise DuplicateEntityError(key)
        self._store[key] = item

    def get(self, key: str) -> Entity:
        """Return the stored entity for ``key``; raises TypeError or KeyError."""
        if not isinstance(key, str):
            raise TypeError("key must be str")
        return self._store[key]

    def remove(self, key: str) -> Entity:
        """Remove and return the entity for ``key``; raises KeyError if missing."""
        if key not in self._store:
            raise KeyError(key)
        return self._store.pop(key)

    def __contains__(self, key: object) -> bool:
        """Return whether ``key`` is a string present in the store."""
        return isinstance(key, str) and key in self._store

    def __len__(self) -> int:
        """Return the number of stored entities."""
        return len(self._store)

    def __iter__(self) -> Iterator[Entity]:
        """Iterate over stored entities in sorted key order."""
        for key in sorted(self._store):
            yield self._store[key]

class SimulationReport:
